# ── Descriptors ──────────────────────────────────────────────────────────────

class TypedDescriptor:
    """Descriptor that enforces a type and optional range constraint."""

    def __init__(self, expected_type: type, lo=None, hi=None):
        self.expected_type = expected_type
        self.lo = lo
        self.hi = hi
        self.name: str = ""

    def __set_name__(self, owner: type, name: str) -> None:
        self.name = f"_{owner.__name__}__{name}"

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        return getattr(obj, self.name, None)

    def __set__(self, obj, value) -> None:
        if not isinstance(value, self.expected_type):
            raise TypeError(
                f"{self.name}: expected {self.expected_type.__name__}, got {type(value).__name__}"
            )
        if self.lo is not None and value < self.lo:
            raise ValueError(f"{self.name}: {value} below minimum {self.lo}")
        if self.hi is not None and value > self.hi:
            raise ValueError(f"{self.name}: {value} above maximum {self.hi}")
        setattr(obj, self.name, value)


class CachedProperty:
    """Non-data descriptor implementing a lazy cached property."""

    def __init__(self, func):
        self.func = func
        self.attrname: Optional[str] = None

    def __set__(self, obj, value):
        setattr(obj, self.attrname, value)

    def __delete__(self, obj):
        delattr(obj, self.attrname)

    def getter(self, func):
        self.func = func
        return self

    def setter(self, func):
        self.func = func
        return self

    def deleter(self, func):
        self.func = func
        return self

    def setter(self, func):
        self.func = func
        return self

    def setter(self, func):
        self.func = func
        return self

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        if self.attrname is None:
            self.attrname = f"_{objtype.__qualname__}__{self.func.__name__}"
        value = self.func(obj)
        setattr(obj, self.attrname, value)
        return value


# ─── Classes ─────────────────────────────────────────────────────────────────

class AClass:
    x: int
    y: int = 42


a = AClass()
b = AClass(3, 4)
c = AClass(1, y=2)
d = AClass(y=6)


def test_class_attribute_access():
    assert a.x == 0
    assert b.x == 3
    assert c.x == 1
    assert d.x == 6


class BClass:
    def __init__(self):
        self.x = 0


x = BClass().x
y = BClass().y
z = BClass(x=1).y


def test_class_attribute_declaration():
    assert x == 0
    assert y == 42
    assert z == 42


class CClass:
    x: int = 0

    def __init__(self):
        self.y = 42


x = CClass().x
y = CClass().y


def test_default_value_declared_at_class_level():
    assert x == 0
    assert y == 42


class DClass:
    def __init__(self):
        self.x = 0


x = DClass().x
y = DClass().y


